static boolean tryTake(AtomicInteger tokens) {
    while (true) {
        int left = tokens.get();
        if (left == 0) return false;                       // nothing left: no write
        if (tokens.compareAndSet(left, left - 1)) return true;
    }                                                      // someone else took one: retry
}

